mapper.insert:
INSERT INTO expense_split_routing(tenant_id,report_id,round_no,application_id,application_version,financial_version,
    definition_id,process_key,definition_version,rule_version,mode,submitted_at,snapshot_json)
SELECT e.tenant_id,e.id,#{roundNo},a.id,a.version,e.version,d.id,d.process_key,d.version,#{ruleVersion},#{mode},#{submittedAt},#{stateJson}
FROM expense_report e JOIN approval_application a ON a.tenant_id=e.tenant_id AND a.id=e.application_id
JOIN approval_definition d ON d.tenant_id=a.tenant_id AND d.process_key=a.process_key AND d.version=a.definition_version
WHERE e.tenant_id=#{tenantId} AND e.id=#{reportId} AND a.id=#{applicationId} AND e.version=#{financialVersion} AND a.version=#{applicationVersion} AND e.current_round_no=#{currentRoundNo}
    AND a.status=#{status} AND a.status IN ('DRAFT','RETURNED','WITHDRAWN')
    AND (CASE WHEN a.status='DRAFT' THEN a.round_no ELSE a.round_no+1 END)=#{roundNo13}
    AND d.id=#{definitionId} AND d.process_key=#{processKey} AND d.version=#{definitionVersion} AND d.status='PUBLISHED'

mapper.select:
SELECT r.*,v.state_json AS financial_state_json FROM expense_split_routing r
JOIN expense_report_revision v ON v.tenant_id=r.tenant_id AND v.report_id=r.report_id AND v.financial_version=r.financial_version
 WHERE r.tenant_id=#{tenantId} AND r.report_id=#{reportId} AND r.round_no=#{roundNo}

SELECT r.*,v.state_json AS financial_state_json FROM expense_split_routing r
JOIN expense_report_revision v ON v.tenant_id=r.tenant_id AND v.report_id=r.report_id AND v.financial_version=r.financial_version
 WHERE r.tenant_id=#{tenantId} AND r.application_id=#{applicationId} AND r.round_no=#{roundNo}
